import java.util.Collections;
import java.util.List;
import org.jfree.chart.util.ObjectUtilities;
import org.jfree.data.general.Series;
import org.jfree.data.general.SeriesChangeEvent;
import org.jfree.data.general.SeriesException;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

public class XYSeries_addOrUpdate_TriageGen1Test {

    private XYSeries series;

    @Before
    public void setUp() {
        // Default series: autoSort = true, allowDuplicateXValues = false
        series = new XYSeries("Test Series");
    }



    @Test
    public void testAddOrUpdate_AllowDuplicatesTrue_ReturnsNull() {
        XYSeries duplicateSeries = new XYSeries("Duplicate Series", true, true);

        XYDataItem result = duplicateSeries.addOrUpdate(1.0, 10.0);

        assertNull("Should return null when allowDuplicateXValues is true", result);
        assertEquals(1, duplicateSeries.getItemCount());
        assertEquals(1.0, duplicateSeries.getX(0).doubleValue(), 0.001);
        assertEquals(10.0, duplicateSeries.getY(0).doubleValue(), 0.001);

        // Add same X again
        duplicateSeries.addOrUpdate(1.0, 20.0);
        assertEquals(2, duplicateSeries.getItemCount());
    }








}

package org.jfree.data.xy;

import java.io.*;
