import org.jfree.data.general.SeriesChangeEvent;
import org.jfree.data.general.SeriesException;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

public class XYSeries_addOrUpdate_TriageGen1Test {

    private XYSeries series;

    @Before
    public void setUp() {
        // Default series: autoSort = true, allowDuplicateXValues = false
        series = new XYSeries("Test Series");
    }





    @Test
    public void testAddOrUpdate_UpdateExistingValue_ReturnsOverwritten() {
        series.add(1.0, 10.0);
        series.add(2.0, 20.0);

        XYDataItem overwritten = series.addOrUpdate(1.0, 15.0);

        assertNotNull("Should return the old data item", overwritten);
        assertEquals(1.0, overwritten.getX().doubleValue(), 0.001);
        assertEquals(10.0, overwritten.getY().doubleValue(), 0.001);
        assertEquals(2, series.getItemCount());
        assertEquals(15.0, series.getY(0).doubleValue(), 0.001);
    }






}

package org.jfree.data.xy;

import java.io.*;
