import org.jfree.data.general.Series;
import org.jfree.data.general.SeriesChangeEvent;
import org.jfree.data.general.SeriesException;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

public class XYSeries_addOrUpdate_TriageGen1Test {

    private XYSeries series;

    @Before
    public void setUp() {
        // Default series: autoSort = true, allowDuplicateXValues = false
        series = new XYSeries("Test Series");
    }







    @Test
    public void testAddOrUpdate_AddNewValue_AutoSortTrue() {
        // Series is autoSort = true by default
        series.add(10.0, 100.0);
        series.add(30.0, 300.0);

        // Add 20.0 in the middle
        XYDataItem result = series.addOrUpdate(20.0, 200.0);

        assertNull("Should return null when adding new item", result);
        assertEquals(3, series.getItemCount());
        // Check sorting order: 10, 20, 30
        assertEquals(10.0, series.getX(0).doubleValue(), 0.001);
        assertEquals(20.0, series.getX(1).doubleValue(), 0.001);
        assertEquals(30.0, series.getX(2).doubleValue(), 0.001);
    }




}

