package org.jfree.data.xy;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import java.util.Collections;
import java.util.List;
import org.jfree.chart.util.ObjectUtilities;
import org.jfree.data.general.Series;
import org.jfree.data.general.SeriesChangeEvent;
import org.jfree.data.general.SeriesException;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

public class XYSeries_addOrUpdate_TriageGen1Test {

    private XYSeries series;

    @Before
    public void setUp() {
        // Default series: autoSort = true, allowDuplicateXValues = false
        series = new XYSeries("Test Series");
    }











    @Test
    public void testAddOrUpdate_ExceedMaximumItemCount_RemovesFirst() {
        series.setMaximumItemCount(2);

        series.addOrUpdate(1.0, 10.0);
        series.addOrUpdate(2.0, 20.0);
        // This should trigger removal of index 0 (1.0, 10.0)
        series.addOrUpdate(3.0, 30.0);

        assertEquals(2, series.getItemCount());
        assertEquals(2.0, series.getX(0).doubleValue(), 0.001);
        assertEquals(3.0, series.getX(1).doubleValue(), 0.001);
    }
}
